function text(s,x,y,size=14,color=INK,align='left'){s=String(s).toUpperCase();const scale=Math.max(1,Math.round(size/7)),width=(s.length*6-1)*scale;if(align==='center')x-=width/2;else if(align==='right')x-=width;for(const c of s){const rows=glyphs[c];if(rows)rows.split('/').forEach((row,iy)=>{for(let ix=0;ix<5;ix++)if(row[ix]==='1')rect(x+ix*scale,y+iy*scale,scale,scale,color);});x+=6*scale;}}
