function tone(f,end,duration=.07,delay=0,vol=.035){if(!settings.sfx||settings.sfxVolume<=0||!audio||!sfxGain)return;const t=audio.currentTime+delay,o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),t+duration);g.gain.setValueAtTime(vol*3,t);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(sfxGain);o.start(t);o.stop(t+duration+.01);o.onended=()=>{o.disconnect();g.disconnect();};if(music&&settings.music&&musicGain){const base=settings.musicVolume,at=audio.currentTime;duckUntil=Math.max(duckUntil,t+duration+.08);musicGain.gain.cancelScheduledValues(at);musicGain.gain.setValueAtTime(base*.4,at);musicGain.gain.setValueAtTime(base*.4,duckUntil);musicGain.gain.linearRampToValueAtTime(base,duckUntil+.08);}}
