function loadBundledTrack(){music=new Audio(BUNDLED_MUSIC.src);music.loop=true;music.volume=1;musicName=BUNDLED_MUSIC.name;musicMessage='BUNDLED LOOP READY';connectMusic();music.addEventListener('error',()=>{musicMessage='BUNDLED MUSIC COULD NOT LOAD';status.textContent=musicMessage;});}
function syncMusic(){applyAudioVolumes();if(!music)return;if(settings.music&&settings.musicVolume>0)music.play().catch(()=>{musicMessage='PRESS A KEY TO PLAY MUSIC';});else music.pause();}
function trackDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('No local storage'));const r=window.indexedDB.open('bn89-music',1);r.onupgradeneeded=()=>r.result.createObjectStore('tracks');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function saveTrack(file){let db;try{db=await trackDB();await new Promise((resolve,reject)=>{const tx=db.transaction('tracks','readwrite');tx.objectStore('tracks').put(file,'loop');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});musicMessage='TRACK SAVED ON THIS DEVICE';}catch{musicMessage='TRACK READY FOR THIS SESSION';}finally{if(db)db.close();}}
function loadTrack(file,play=true){if(music)music.pause();if(musicUrl)URL.revokeObjectURL(musicUrl);musicUrl=URL.createObjectURL(file);music=new Audio(musicUrl);music.loop=true;music.volume=1;connectMusic();musicName=file.name||'YOUR TRACK';musicMessage='TRACK READY';music.addEventListener('error',()=>{musicMessage='AUDIO FORMAT NOT SUPPORTED';status.textContent=musicMessage;});if(play){settings.music=true;settings.musicCustom=true;applyPalette();syncMusic();}}
async function restoreTrack(){let db;try{db=await trackDB();const file=await new Promise((resolve,reject)=>{const r=db.transaction('tracks').objectStore('tracks').get('loop');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(file)loadTrack(file,false);}catch{}finally{if(db)db.close();}}
