function downAir(p){return !!(p.attack&&p.attack.dir[1]===1);}
function cancelDownAir(p){if(downAir(p)&&now>=p.attack.cancelAt){endAction(p,false);return true;}return false;}
function startAirDash(p,dir){if(p.ground||!canAct(p)||now<p.switchReady)return false;if(p.kind&&p.kind!=='shield'&&!cancelDownAir(p))return false;endAction(p,false);resetPunchChain(p);p.recovery=null;p.recoveryLock=true;p.airDashing=true;p.knockback=false;p.pogoFloat=false;p.bombSlowUntil=0;p.wallDir=0;p.wallContactUntil=0;p.launchAttack=null;p.jumpRising=false;p.jumpHeld=false;p.sprint=0;p.vx=dir*T.launch;p.vy=0;p.face=dir;p.launchUntil=now+T.airDashBurst;p.dashPickupUntil=p.launchUntil+T.dodgeCooldown;p.airTap={dir:0,time:-10};burst(p.x+18,p.y+21,10);sfx('jump');return true;}
function canAct(p){return !p.respawnAt&&p.lives>0&&now>=p.stun&&now>=p.inv&&now>=p.dodgeReadyUntil&&!p.recoveryLock&&!p.recovery;}
function beginRecovery(p){if(p.kind==='charge'&&now-p.chargeStart>T.chord)return false;if(p.ground||!canAct(p)||now<p.switchReady&&p.kind!=='charge'&&p.kind!=='shoot')return false;endAction(p,false);resetPunchChain(p);p.knockback=false;p.pogoFloat=false;p.bombSlowUntil=0;p.recovery={until:now+T.aim,angle:0};p.recoveryLock=true;p.kind='aim';p.jumpRising=false;p.sprint=0;p.jumpHeld=false;p.vx*=T.aimMoveScale;if(p.vy>0)p.vy*=T.aimFallScale;tone(320,650,.12);return true;}
